// Postgres implementation of LiveStore over an injected minimal client, so
// tests need no driver. Every SQL string is a constant and parameterized.
// Any client failure becomes LiveStoreUnavailable (callers fail closed).

import {
  LiveStoreUnavailable,
  type CodeSummary,
  type HitResult,
  type LiveStore,
  type ReserveResult,
  type RunOutcome,
} from "./store";

export interface PgQueryable {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  query(text: string, params?: unknown[]): Promise<{ rows: any[] }>;
}

export interface PgDb extends PgQueryable {
  // Runs fn on one connection inside BEGIN/COMMIT (ROLLBACK on throw).
  transaction<T>(fn: (tx: PgQueryable) => Promise<T>): Promise<T>;
}

const SQL = {
  getSetting: "SELECT value FROM settings WHERE key = $1",
  setSetting:
    "INSERT INTO settings (key, value) VALUES ($1, $2) " +
    "ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value",
  reserve:
    "UPDATE invite_codes SET runs_used = runs_used + 1, " +
    "locked_until = $2::timestamptz + make_interval(secs => $3), " +
    "last_used_at = $2::timestamptz " +
    "WHERE code_hash = $1 AND NOT disabled AND runs_used < max_runs " +
    "AND (locked_until IS NULL OR locked_until <= $2::timestamptz) " +
    "RETURNING id, max_runs - runs_used AS remaining",
  reserveReason:
    "SELECT disabled, runs_used >= max_runs AS exhausted FROM invite_codes " +
    "WHERE code_hash = $1",
  insertRun:
    "INSERT INTO live_runs (invite_code_id, status, started_at) " +
    "VALUES ($1, 'started', $2::timestamptz) RETURNING id",
  finishRun:
    "UPDATE live_runs SET status = $2, finished_at = now(), searched = $3, " +
    "enriched = $4, provider_cost_usd = $5, model_cost_usd = $6, " +
    "error_category = $7 WHERE id = $1 AND status = 'started' " +
    "RETURNING invite_code_id",
  releaseRun:
    "UPDATE live_runs SET status = 'released', finished_at = now() " +
    "WHERE id = $1 AND status = 'started' RETURNING invite_code_id",
  unlock: "UPDATE invite_codes SET locked_until = NULL WHERE id = $1",
  giveBack:
    "UPDATE invite_codes SET runs_used = GREATEST(runs_used - 1, 0), " +
    "locked_until = NULL WHERE id = $1",
  hit:
    "INSERT INTO rate_hits (bucket, window_start, count) VALUES ($1, $2::timestamptz, 1) " +
    "ON CONFLICT (bucket, window_start) DO UPDATE SET count = rate_hits.count + 1 " +
    "RETURNING count",
  createCode:
    "INSERT INTO invite_codes (label, max_runs, code_hash) VALUES ($1, $2, $3) " +
    "ON CONFLICT DO NOTHING RETURNING id",
  listCodes:
    "SELECT label, max_runs, runs_used, disabled FROM invite_codes ORDER BY created_at, label",
  setDisabled:
    "UPDATE invite_codes SET disabled = $2 WHERE label = $1 RETURNING id",
  addRuns:
    "UPDATE invite_codes SET max_runs = max_runs + $2 WHERE label = $1 RETURNING id",
} as const;

async function guard<T>(fn: () => Promise<T>): Promise<T> {
  try {
    return await fn();
  } catch {
    throw new LiveStoreUnavailable();
  }
}

export class PgLiveStore implements LiveStore {
  constructor(private readonly db: PgDb) {}

  isLiveEnabled(): Promise<boolean> {
    return guard(async () => {
      const { rows } = await this.db.query(SQL.getSetting, ["live_enabled"]);
      return rows[0]?.value === "true";
    });
  }

  setLiveEnabled(value: boolean): Promise<void> {
    return guard(async () => {
      await this.db.query(SQL.setSetting, ["live_enabled", String(value)]);
    });
  }

  reserveRun(
    codeHash: string,
    now: Date,
    lockSeconds: number,
  ): Promise<ReserveResult> {
    return guard(() =>
      this.db.transaction(async (tx): Promise<ReserveResult> => {
        const iso = now.toISOString();
        const upd = await tx.query(SQL.reserve, [codeHash, iso, lockSeconds]);
        if (upd.rows.length === 0) {
          const { rows } = await tx.query(SQL.reserveReason, [codeHash]);
          const row = rows[0];
          if (!row) return { ok: false, reason: "invalid_code" };
          if (row.disabled) return { ok: false, reason: "disabled" };
          if (row.exhausted) return { ok: false, reason: "no_runs_left" };
          return { ok: false, reason: "run_in_progress" };
        }
        const { id, remaining } = upd.rows[0];
        const ins = await tx.query(SQL.insertRun, [id, iso]);
        return {
          ok: true,
          runId: String(ins.rows[0].id),
          runsRemaining: Number(remaining),
        };
      }),
    );
  }

  finishRun(runId: string, outcome: RunOutcome): Promise<void> {
    return guard(() =>
      this.db.transaction(async (tx) => {
        const { rows } = await tx.query(SQL.finishRun, [
          runId,
          outcome.status,
          outcome.searched,
          outcome.enriched,
          outcome.providerCostUsd,
          outcome.modelCostUsd,
          outcome.errorCategory ?? null,
        ]);
        if (rows[0]) await tx.query(SQL.unlock, [rows[0].invite_code_id]);
      }),
    );
  }

  releaseRun(runId: string): Promise<void> {
    return guard(() =>
      this.db.transaction(async (tx) => {
        const { rows } = await tx.query(SQL.releaseRun, [runId]);
        if (rows[0]) await tx.query(SQL.giveBack, [rows[0].invite_code_id]);
      }),
    );
  }

  hit(
    bucket: string,
    now: Date,
    windowSeconds: number,
    limit: number,
  ): Promise<HitResult> {
    return guard(async () => {
      const windowMs = windowSeconds * 1000;
      const start = Math.floor(now.getTime() / windowMs) * windowMs;
      const { rows } = await this.db.query(SQL.hit, [
        bucket,
        new Date(start).toISOString(),
      ]);
      const count = Number(rows[0].count);
      if (count <= limit) return { allowed: true, retryAfterSeconds: 0 };
      const retry = Math.ceil((start + windowMs - now.getTime()) / 1000);
      return { allowed: false, retryAfterSeconds: Math.max(retry, 1) };
    });
  }

  readonly admin: LiveStore["admin"] = {
    createCode: (label, maxRuns, codeHash) =>
      guard(async () => {
        const { rows } = await this.db.query(SQL.createCode, [
          label,
          maxRuns,
          codeHash,
        ]);
        return rows.length > 0;
      }),
    listCodes: () =>
      guard(async (): Promise<CodeSummary[]> => {
        const { rows } = await this.db.query(SQL.listCodes);
        return rows.map((r) => ({
          label: String(r.label),
          maxRuns: Number(r.max_runs),
          runsUsed: Number(r.runs_used),
          disabled: Boolean(r.disabled),
        }));
      }),
    disableCode: (label) =>
      guard(async () => {
        const { rows } = await this.db.query(SQL.setDisabled, [label, true]);
        return rows.length > 0;
      }),
    enableCode: (label) =>
      guard(async () => {
        const { rows } = await this.db.query(SQL.setDisabled, [label, false]);
        return rows.length > 0;
      }),
    addRuns: (label, n) =>
      guard(async () => {
        const { rows } = await this.db.query(SQL.addRuns, [label, n]);
        return rows.length > 0;
      }),
  };
}

// Real driver wiring. pg is imported lazily so unit tests never load it.
export async function connectPgStore(
  databaseUrl: string,
  options: { searchPath?: string } = {},
): Promise<{ store: PgLiveStore; close(): Promise<void> }> {
  const { Pool } = await import("pg");
  const pool = new Pool({
    connectionString: databaseUrl,
    ...(options.searchPath
      ? { options: `-c search_path=${options.searchPath}` }
      : {}),
  });
  const db: PgDb = {
    query: (text, params) => pool.query(text, params),
    async transaction(fn) {
      const client = await pool.connect();
      try {
        await client.query("BEGIN");
        const out = await fn({ query: (t, p) => client.query(t, p) });
        await client.query("COMMIT");
        return out;
      } catch (err) {
        await client.query("ROLLBACK").catch(() => undefined);
        throw err;
      } finally {
        client.release();
      }
    },
  };
  return { store: new PgLiveStore(db), close: () => pool.end() };
}
EOF
cat > scripts/live-admin.ts <<'EOF'
// Admin CLI for live mode. Reads DATABASE_URL and INVITE_HMAC_SECRET from the
// environment, never prints them, and prints a new invite code exactly once.
// Exit codes: 0 ok, 1 failure, 2 usage.

import { pathToFileURL } from "node:url";
import { generateInviteCode, hashCode } from "../src/server/live/codes";
import { connectPgStore } from "../src/server/live/pg-store";
import type { LiveStore } from "../src/server/live/store";

export const EXIT_OK = 0;
export const EXIT_FAILED = 1;
export const EXIT_USAGE = 2;

const USAGE = `usage:
  live-admin create --label X --runs N
  live-admin list
  live-admin disable --label X
  live-admin enable --label X
  live-admin add-runs --label X --n N
  live-admin kill-switch on|off|status`;

export type AdminCommand =
  | { kind: "create"; label: string; runs: number }
  | { kind: "list" }
  | { kind: "disable"; label: string }
  | { kind: "enable"; label: string }
  | { kind: "add-runs"; label: string; n: number }
  | { kind: "kill-switch"; action: "on" | "off" | "status" };

class UsageError extends Error {}

function flags(args: string[], names: string[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (let i = 0; i < args.length; i += 2) {
    const name = args[i]?.replace(/^--/, "");
    const value = args[i + 1];
    if (!args[i]?.startsWith("--") || !names.includes(name) || !value) {
      throw new UsageError("bad flags");
    }
    out[name] = value;
  }
  if (names.some((n) => !(n in out))) throw new UsageError("missing flag");
  return out;
}

function count(text: string, min: number): number {
  if (!/^\d+$/.test(text) || Number(text) < min) throw new UsageError("bad number");
  return Number(text);
}

export function parseAdminArgs(argv: string[]): AdminCommand {
  const [cmd, ...rest] = argv;
  switch (cmd) {
    case "create": {
      const f = flags(rest, ["label", "runs"]);
      return { kind: "create", label: f.label, runs: count(f.runs, 0) };
    }
    case "list":
      if (rest.length) throw new UsageError("unexpected args");
      return { kind: "list" };
    case "disable":
    case "enable":
      return { kind: cmd, label: flags(rest, ["label"]).label };
    case "add-runs": {
      const f = flags(rest, ["label", "n"]);
      return { kind: "add-runs", label: f.label, n: count(f.n, 1) };
    }
    case "kill-switch":
      if (rest.length !== 1 || !["on", "off", "status"].includes(rest[0])) {
        throw new UsageError("bad action");
      }
      return { kind: "kill-switch", action: rest[0] as "on" | "off" | "status" };
    default:
      throw new UsageError("unknown command");
  }
}

async function execute(
  cmd: AdminCommand,
  store: LiveStore,
  secret: string,
  out: (line: string) => void,
): Promise<number> {
  const missing = (label: string) => {
    out(`no code with label "${label}"`);
    return EXIT_FAILED;
  };
  switch (cmd.kind) {
    case "create": {
      const code = generateInviteCode();
      if (!(await store.admin.createCode(cmd.label, cmd.runs, hashCode(code, secret)))) {
        out(`label "${cmd.label}" already exists`);
        return EXIT_FAILED;
      }
      out(`created "${cmd.label}" with ${cmd.runs} runs`);
      out(`code (shown once, store it now): ${code}`);
      return EXIT_OK;
    }
    case "list": {
      for (const c of await store.admin.listCodes()) {
        out(
          `${c.label}\t${c.runsUsed}/${c.maxRuns} used\t${c.disabled ? "disabled" : "enabled"}`,
        );
      }
      return EXIT_OK;
    }
    case "disable":
    case "enable": {
      const found =
        cmd.kind === "disable"
          ? await store.admin.disableCode(cmd.label)
          : await store.admin.enableCode(cmd.label);
      if (!found) return missing(cmd.label);
      out(`${cmd.kind}d "${cmd.label}"`);
      return EXIT_OK;
    }
    case "add-runs":
      if (!(await store.admin.addRuns(cmd.label, cmd.n))) return missing(cmd.label);
      out(`added ${cmd.n} runs to "${cmd.label}"`);
      return EXIT_OK;
    case "kill-switch":
      if (cmd.action === "status") {
        out(`live mode is ${(await store.isLiveEnabled()) ? "ON" : "OFF"}`);
      } else {
        await store.setLiveEnabled(cmd.action === "on");
        out(`live mode is now ${cmd.action.toUpperCase()}`);
      }
      return EXIT_OK;
  }
}

async function main(): Promise<number> {
  let cmd: AdminCommand;
  try {
    cmd = parseAdminArgs(process.argv.slice(2));
  } catch {
    console.error(USAGE);
    return EXIT_USAGE;
  }
  const databaseUrl = process.env.DATABASE_URL;
  const secret = process.env.INVITE_HMAC_SECRET;
  if (!databaseUrl || !secret) {
    console.error("DATABASE_URL and INVITE_HMAC_SECRET must both be set");
    return EXIT_FAILED;
  }
  let close: (() => Promise<void>) | undefined;
  try {
    const conn = await connectPgStore(databaseUrl);
    close = conn.close;
    return await execute(cmd, conn.store, secret, (l) => console.log(l));
  } catch (err) {
    // Only the error class: messages from drivers can echo connection details.
    console.error(`failed: ${err instanceof Error ? err.name : "error"}`);
    return EXIT_FAILED;
  } finally {
    await close?.().catch(() => undefined);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().then((code) => process.exit(code));
}
EOF

cat > tests/live/codes.test.ts <<'EOF'
import { describe, expect, it } from "vitest";
import {
  generateInviteCode,
  hashCode,
  hashIp,
  normalizeCode,
} from "../../src/server/live/codes";

const SECRET = "s".repeat(40);
const OTHER = "t".repeat(40);

describe("generateInviteCode", () => {
  it("is 32 Crockford base32 characters in dash-separated groups", () => {
    const code = generateInviteCode();
    expect(code).toMatch(/^([0-9A-HJKMNP-TV-Z]{4}-){7}[0-9A-HJKMNP-TV-Z]{4}$/);
  });

  it("does not repeat", () => {
    const codes = new Set(Array.from({ length: 200 }, generateInviteCode));
    expect(codes.size).toBe(200);
  });
});

describe("normalizeCode", () => {
  it("trims, uppercases and removes dashes and spaces", () => {
    expect(normalizeCode("  ab12-cd 34-ef  ")).toBe("AB12CD34EF");
  });
});

describe("hashCode / hashIp", () => {
  it("is a stable hex HMAC independent of formatting", () => {
    const a = hashCode("ABCD-1234", SECRET);
    expect(a).toMatch(/^[0-9a-f]{64}$/);
    expect(hashCode(" abcd 1234 ", SECRET)).toBe(a);
  });

  it("depends on the secret", () => {
    expect(hashCode("ABCD1234", SECRET)).not.toBe(hashCode("ABCD1234", OTHER));
    expect(hashIp("1.2.3.4", SECRET)).not.toBe(hashIp("1.2.3.4", OTHER));
  });

  it("uses a different domain for ips than for codes", () => {
    expect(hashIp("ABCD1234", SECRET)).not.toBe(hashCode("ABCD1234", SECRET));
  });

  it("rejects short secrets without leaking code or secret", () => {
    const short = "short-secret-value";
    for (const fn of [
      () => hashCode("SECRETCODE99", short),
      () => hashIp("9.9.9.9", short),
    ]) {
      let message = "";
      try {
        fn();
      } catch (e) {
        message = (e as Error).message;
      }
      expect(message).not.toBe("");
      expect(message).not.toContain(short);
      expect(message).not.toContain("SECRETCODE99");
      expect(message).not.toContain("9.9.9.9");
    }
  });
});
