describe("PgLiveStore SQL hygiene", () => {
  it("parameterizes every statement and never interpolates inputs", async () => {
    const evil = "x'; DROP TABLE invite_codes; --";
    const { db, calls } = fakeDb([
      { rows: [{ value: "true" }] },
