      (s) => s.admin.enableCode("l"),
      (s) => s.admin.addRuns("l", 1),
    ];
    for (const call of calls) {
      const { db } = fakeDb([boom, boom, boom]);
      const err = await call(new PgLiveStore(db)).catch((e) => e);
